import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,ag as l}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Tailscale 学习地图","description":"Tailscale 是一张「登录同一账号的设备互相连通」的加密网络。这一页是产品全景加决策表：先回答「我要连什么、该用哪个功能」，再进教程和源码页。","frontmatter":{"title":"Tailscale 学习地图","description":"Tailscale 是一张「登录同一账号的设备互相连通」的加密网络。这一页是产品全景加决策表：先回答「我要连什么、该用哪个功能」，再进教程和源码页。","domain":"product","tags":["mesh-vpn","remote-access","tailscale"],"role":"map"},"headers":[],"relativePath":"zh/products/tailscale/index.md","filePath":"zh/products/tailscale/index.md","lastUpdated":1795592559000}'),s={name:"zh/products/tailscale/index.md"};function d(o,t,c,i,n,h){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="tailscale-学习地图" tabindex="-1">Tailscale 学习地图 <a class="header-anchor" href="#tailscale-学习地图" aria-label="Permalink to &quot;Tailscale 学习地图&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> Tailscale 让<strong>登录了同一个账号的设备</strong>互相连通，数据端到端加密，不需要公网 IP 和端口转发。它是一组功能的集合，不是一个单一产品：先弄清「我要连什么」，再选下面的哪一项。</p><p>官方定义（<a href="https://tailscale.com/docs/concepts/what-is-tailscale" target="_blank" rel="noreferrer">What is Tailscale?</a>）：一个基于身份的零信任连接平台，用开源的 WireGuard 协议建立加密的点对点连接，组成一张叫 <strong>tailnet</strong> 的对等网络。本页是<strong>地图</strong>，动手请进<a href="./tailscale.html">教程</a>。</p></blockquote><h2 id="写给谁-先决条件-非目标" tabindex="-1">写给谁 / 先决条件 / 非目标 <a class="header-anchor" href="#写给谁-先决条件-非目标" aria-label="Permalink to &quot;写给谁 / 先决条件 / 非目标&quot;">​</a></h2><ul><li><strong>写给谁：</strong> 想从外面访问自己的另一台设备（台式机、笔记本、NAS、云上的虚拟机），又不想研究组网的前端或 AI 应用开发者。</li><li><strong>先决条件：</strong> 一个身份提供商的账号（Google、GitHub、Microsoft、Apple、Okta、OneLogin 之一，或自定义 OpenID Connect）；两台设备。</li><li><strong>非目标：</strong><ul><li>不把它当翻墙或更换地区的工具。自建 exit node 只是把出口换成你自己的设备。</li><li>不讲 WireGuard 本身的密码学。</li><li>Kubernetes Operator、Tailnet Lock、OAuth clients 等进阶主题在本页各占一行，只给官方链接。</li></ul></li></ul><h2 id="产品家族" tabindex="-1">产品家族 <a class="header-anchor" href="#产品家族" aria-label="Permalink to &quot;产品家族&quot;">​</a></h2><p>下表的「官方名称」抄自 2026-11-24 打开的官方文档索引（<a href="https://tailscale.com/docs/llms.txt" target="_blank" rel="noreferrer">Tailscale Documentation</a>）。本目录只有三页：本地图、<a href="./tailscale.html">教程</a>、<a href="./source.html">源码解读</a>。</p><table tabindex="0"><thead><tr><th>官方名称</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>Install Tailscale on Windows / macOS / Linux / iOS / Android</strong></td><td><a href="https://tailscale.com/docs/install/windows" target="_blank" rel="noreferrer">Windows</a> · <a href="https://tailscale.com/docs/install/mac" target="_blank" rel="noreferrer">macOS</a> · <a href="https://tailscale.com/docs/install/linux" target="_blank" rel="noreferrer">Linux</a> · <a href="https://tailscale.com/docs/install/ios" target="_blank" rel="noreferrer">iOS</a> · <a href="https://tailscale.com/docs/install/android" target="_blank" rel="noreferrer">Android</a></td><td>教程「安装」一节</td></tr><tr><td><strong>Tailscale CLI</strong></td><td><a href="https://tailscale.com/docs/reference/tailscale-cli" target="_blank" rel="noreferrer">tailscale.com/docs/reference/tailscale-cli</a></td><td>教程贯穿使用，参数以 <code>--help</code> 为准</td></tr><tr><td><strong>Tailscale SSH</strong></td><td><a href="https://tailscale.com/docs/features/tailscale-ssh" target="_blank" rel="noreferrer">tailscale.com/docs/features/tailscale-ssh</a></td><td>教程「日常用法」与「安全与隐私要点」</td></tr><tr><td><strong>Tailscale Serve</strong></td><td><a href="https://tailscale.com/docs/features/tailscale-serve" target="_blank" rel="noreferrer">tailscale.com/docs/features/tailscale-serve</a></td><td>教程「日常用法」</td></tr><tr><td><strong>Tailscale Funnel</strong></td><td><a href="https://tailscale.com/docs/features/tailscale-funnel" target="_blank" rel="noreferrer">tailscale.com/docs/features/tailscale-funnel</a></td><td>教程只讲安全护栏，不教怎么开</td></tr><tr><td><strong>Subnet routers</strong></td><td><a href="https://tailscale.com/docs/features/subnet-routers" target="_blank" rel="noreferrer">tailscale.com/docs/features/subnet-routers</a></td><td>教程「日常用法」</td></tr><tr><td><strong>Exit nodes (route all traffic)</strong></td><td><a href="https://tailscale.com/docs/features/exit-nodes" target="_blank" rel="noreferrer">tailscale.com/docs/features/exit-nodes</a></td><td>教程「日常用法」与「安全与隐私要点」</td></tr><tr><td><strong>Mullvad exit nodes</strong>（付费附加项，beta）</td><td><a href="https://tailscale.com/docs/features/exit-nodes/mullvad-exit-nodes" target="_blank" rel="noreferrer">tailscale.com/docs/features/exit-nodes/mullvad-exit-nodes</a></td><td>地图一行：用 Mullvad 的服务器而不是你自己的设备当出口</td></tr><tr><td><strong>Tailscale Peer Relays</strong></td><td><a href="https://tailscale.com/docs/features/peer-relay" target="_blank" rel="noreferrer">tailscale.com/docs/features/peer-relay</a></td><td>地图一行：直连不通时，让 tailnet 里另一台设备当中转</td></tr><tr><td><strong>Taildrop</strong>（alpha）</td><td><a href="https://tailscale.com/docs/features/taildrop" target="_blank" rel="noreferrer">tailscale.com/docs/features/taildrop</a></td><td>教程「日常用法」</td></tr><tr><td><strong>MagicDNS</strong></td><td><a href="https://tailscale.com/docs/features/magicdns" target="_blank" rel="noreferrer">tailscale.com/docs/features/magicdns</a></td><td>教程「日常用法」</td></tr><tr><td><strong>admin console 与 tailnet policy file</strong>（旧称 ACL，新写法是 grants）</td><td><a href="https://tailscale.com/docs/features/tailnet-policy-file" target="_blank" rel="noreferrer">tailnet-policy-file</a> · <a href="https://tailscale.com/docs/features/access-control" target="_blank" rel="noreferrer">Access control</a></td><td>教程「安全与隐私要点」</td></tr><tr><td><strong>Group devices with tags</strong></td><td><a href="https://tailscale.com/docs/features/tags" target="_blank" rel="noreferrer">tailscale.com/docs/features/tags</a></td><td>地图一行；教程术语表有一行</td></tr><tr><td><strong>Key expiry</strong></td><td><a href="https://tailscale.com/docs/features/access-control/key-expiry" target="_blank" rel="noreferrer">tailscale.com/docs/features/access-control/key-expiry</a></td><td>教程「安全与隐私要点」</td></tr><tr><td><strong>Device approval</strong></td><td><a href="https://tailscale.com/docs/features/access-control/device-management/device-approval" target="_blank" rel="noreferrer">tailscale.com/docs/features/access-control/device-management/device-approval</a></td><td>教程「安全与隐私要点」</td></tr><tr><td><strong>Personal / Standard / Premium / Enterprise</strong>（套餐）</td><td><a href="https://tailscale.com/pricing" target="_blank" rel="noreferrer">tailscale.com/pricing</a></td><td>教程「计费、额度与限制」</td></tr><tr><td><strong>Tailscale SSH session recording</strong></td><td><a href="https://tailscale.com/docs/features/tsrecorder" target="_blank" rel="noreferrer">tailscale.com/docs/features/tsrecorder</a></td><td>地图一行：把 SSH 会话录下来存到自己的录制节点</td></tr><tr><td><strong>tsnet</strong></td><td><a href="https://tailscale.com/docs/features/tsnet" target="_blank" rel="noreferrer">tailscale.com/docs/features/tsnet</a></td><td>地图一行：把 Tailscale 嵌进 Go 程序</td></tr><tr><td><strong>Tailscale Kubernetes Operator</strong></td><td><a href="https://tailscale.com/docs/kubernetes-operator" target="_blank" rel="noreferrer">tailscale.com/docs/kubernetes-operator</a></td><td>地图一行</td></tr><tr><td><strong>Tailnet Lock</strong></td><td><a href="https://tailscale.com/docs/features/tailnet-lock" target="_blank" rel="noreferrer">tailscale.com/docs/features/tailnet-lock</a></td><td>地图一行：新节点要经你指定的节点签名才能加入</td></tr><tr><td><strong>OAuth clients</strong></td><td><a href="https://tailscale.com/docs/features/oauth-clients" target="_blank" rel="noreferrer">tailscale.com/docs/features/oauth-clients</a></td><td>地图一行：让程序持续访问 Tailscale API</td></tr><tr><td><strong>Aperture by Tailscale / Tailscale PAM</strong></td><td><a href="https://tailscale.com/docs/aperture/what-is-aperture" target="_blank" rel="noreferrer">Aperture</a> · <a href="https://tailscale.com/docs/privileged-access-management/what-is-tailscale-pam" target="_blank" rel="noreferrer">PAM</a></td><td>地图一行：同厂的另外两个产品，不属于「把设备连起来」这件事</td></tr></tbody></table><h3 id="个人版与组织版-tailnet-归谁" tabindex="-1">个人版与组织版：tailnet 归谁 <a class="header-anchor" href="#个人版与组织版-tailnet-归谁" aria-label="Permalink to &quot;个人版与组织版：tailnet 归谁&quot;">​</a></h3><table tabindex="0"><thead><tr><th>情况</th><th>结果</th></tr></thead><tbody><tr><td>用公共邮箱注册（比如 Gmail、个人 GitHub 账号）</td><td>视为个人使用，自动进入免费的 Personal 套餐</td></tr><tr><td>用自定义域名注册</td><td>视为商业使用，自动进入 14 天的 Enterprise 试用</td></tr><tr><td>tailnet 用的是自定义域名</td><td>同域名下邮箱的用户不用邀请就能登录；其他人要发外部邀请</td></tr><tr><td>一台设备想同时属于个人 tailnet 和公司 tailnet</td><td>可以注册到多个 tailnet，用客户端切换；但一个节点同一时间只属于一个 tailnet</td></tr></tbody></table><p>来源：<a href="https://tailscale.com/pricing" target="_blank" rel="noreferrer">Tailscale pricing</a> 的 FAQ、<a href="https://tailscale.com/docs/how-to/quickstart" target="_blank" rel="noreferrer">Tailscale quickstart</a>、<a href="https://tailscale.com/docs/concepts/tailscale-identity" target="_blank" rel="noreferrer">Tailscale identity</a>。</p><h3 id="容易撞名" tabindex="-1">容易撞名 <a class="header-anchor" href="#容易撞名" aria-label="Permalink to &quot;容易撞名&quot;">​</a></h3><ul><li><strong>Tailscale 不是传统 VPN。</strong> 官方的对比：传统 VPN 的流量都经过一个中心网关，网关可能离用户很远，延迟高，还会成为瓶颈；Tailscale 让设备直接互连。但你也可以借 exit node 把它当传统 VPN 用。</li><li><strong>Tailscale 不是 WireGuard 本身。</strong> WireGuard 是协议。官方说明：Tailscale 建在 WireGuard 之上，另外加了 NAT 穿透、TCP 传输能力和访问策略。</li><li><strong>Tailscale SSH 不是普通 SSH。</strong> 它接管目标机 Tailscale IP 上的 22 端口，用 Tailscale 身份而不是密钥对来认证。</li><li><strong>Serve 不是 Funnel。</strong> Serve 只给 tailnet 内看；Funnel 给整个互联网看。</li><li><strong>exit node 不是 subnet router。</strong> 前者转发你的全部上网流量；后者让你访问某个私有网段，不影响上网流量。</li><li><strong>Taildrop 不是 Taildrive。</strong> 前者是在自己的设备之间发送文件；后者是在 tailnet 内共享文件夹（本页各占一行，<a href="https://tailscale.com/docs/features/taildrive" target="_blank" rel="noreferrer">Taildrive</a>）。</li><li><strong>Tailscale 不是 Aperture，也不是 Tailscale PAM。</strong> 后两者是同厂的 AI 网关产品和特权访问管理产品。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><h3 id="没有-tailscale-与有-tailscale" tabindex="-1">没有 Tailscale 与有 Tailscale <a class="header-anchor" href="#没有-tailscale-与有-tailscale" aria-label="Permalink to &quot;没有 Tailscale 与有 Tailscale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>我要做的事</th><th>传统做法</th><th>用 Tailscale</th></tr></thead><tbody><tr><td>在外面访问家里或公司的另一台设备</td><td>公网 IP 加路由器端口转发，或者自建 VPN 服务器</td><td>登录同一个账号，用设备名或 <code>100.x.y.z</code> 地址直接连</td></tr><tr><td>SSH 到自己的机器</td><td>生成密钥对，再把公钥分发到目标机</td><td>Tailscale SSH 按 tailnet 策略授权，不用分发公钥</td></tr><tr><td>把本机的开发服务器给别人看</td><td>部署到公网，或做内网穿透</td><td><code>tailscale serve</code>，只对 tailnet 开放</td></tr><tr><td>访问家里没装客户端的设备</td><td>每台设备单独做端口转发</td><td>一台子网路由器代为转发</td></tr><tr><td>两台设备之间加密通信</td><td>自己配置 WireGuard，手动生成并分发密钥</td><td>登录后自动生成和分发密钥</td></tr></tbody></table><p>表中「传统做法」的描述来自官方页面对比：连接「不需要端口转发或复杂的防火墙规则」；不借助 Tailscale 使用 WireGuard 时，用户要手动生成并分发密钥。</p><h3 id="与替代方案对比" tabindex="-1">与替代方案对比 <a class="header-anchor" href="#与替代方案对比" aria-label="Permalink to &quot;与替代方案对比&quot;">​</a></h3><p>只写能在官方页面找到依据的事实。</p><table tabindex="0"><thead><tr><th>方案</th><th>流量路径</th><th>密钥与身份</th><th>依据</th></tr></thead><tbody><tr><td>传统 VPN（中心网关）</td><td>全部经过网关</td><td>由管理员配置</td><td>网关可能离用户很远，延迟更高；集中之后成为瓶颈</td></tr><tr><td>自己配置 WireGuard</td><td>端点之间</td><td>手动生成并分发密钥</td><td>官方把它列为 Tailscale 要替用户自动化的工作</td></tr><tr><td>Tailscale</td><td>尽量直连，不通时走 DERP 中继</td><td>身份提供商登录，密钥自动分发</td><td>三种连接方式都端到端加密</td></tr><tr><td>自建协调服务器（如 Headscale）</td><td>同 Tailscale 客户端</td><td>同 Tailscale</td><td>官方有一页讲怎么让客户端改用自建的控制服务器</td></tr><tr><td>画面串流类远程桌面</td><td>不适用</td><td>不适用</td><td>解决的是另一个问题：看到并操作另一台机器的画面，见 <a href="./../uu-remote/">UU Remote</a></td></tr></tbody></table><p>来源：<a href="https://tailscale.com/docs/concepts/what-is-tailscale" target="_blank" rel="noreferrer">What is Tailscale?</a>、<a href="https://tailscale.com/docs/concepts/wireguard" target="_blank" rel="noreferrer">About WireGuard</a>、<a href="https://tailscale.com/docs/concepts/tailscale-identity" target="_blank" rel="noreferrer">Tailscale identity</a>、<a href="https://tailscale.com/docs/reference/connection-types" target="_blank" rel="noreferrer">Connection types</a>、<a href="https://tailscale.com/docs/how-to/set-up-custom-coordination-server" target="_blank" rel="noreferrer">custom control server</a>。</p><h2 id="快速决策-我的情况该用什么" tabindex="-1">快速决策：我的情况该用什么 <a class="header-anchor" href="#快速决策-我的情况该用什么" aria-label="Permalink to &quot;快速决策：我的情况该用什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我的情况</th><th>用什么</th></tr></thead><tbody><tr><td>在外面 SSH 回自己的 Linux 机器</td><td>Tailscale SSH</td></tr><tr><td>目标机是 Windows 或 macOS 的 App Store 版</td><td>装好 Tailscale 后用系统自带的普通 SSH 或远程桌面，目标写设备名</td></tr><tr><td>把本机的开发服务器给 tailnet 里的人看</td><td>Tailscale Serve</td></tr><tr><td>把一个服务开放给公网</td><td>Tailscale Funnel，先读教程里的安全护栏</td></tr><tr><td>访问家里没装客户端的设备（打印机、NAS 的管理页）</td><td>Subnet router</td></tr><tr><td>在公共 Wi-Fi 下让流量从家里出去</td><td>Exit node</td></tr><tr><td>在自己的设备之间传文件</td><td>Taildrop</td></tr><tr><td>tailnet 里要加别人</td><td>先收紧 tailnet policy file</td></tr><tr><td>服务器或 GPU 机器要长期在线</td><td>Disable key expiry；进阶做法是给设备贴 tag</td></tr><tr><td>一直走中继，嫌慢</td><td>先跑 <code>tailscale netcheck</code> 看原因，再考虑 Tailscale Peer Relays</td></tr><tr><td>想把 Tailscale 嵌进自己的 Go 程序</td><td>tsnet</td></tr><tr><td>在 Kubernetes 集群里用</td><td>Tailscale Kubernetes Operator</td></tr></tbody></table><h2 id="本目录怎么读" tabindex="-1">本目录怎么读 <a class="header-anchor" href="#本目录怎么读" aria-label="Permalink to &quot;本目录怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>读完能做什么</th><th>什么时候读</th></tr></thead><tbody><tr><td><a href="./tailscale.html">教程</a></td><td>装好两台设备并确认互通；用 Tailscale SSH 登录；跑通 Serve、子网路由、exit node、Taildrop；知道六条安全护栏</td><td>现在。零前置</td></tr><tr><td><a href="./source.html">源码解读</a></td><td>说清一条连接在代码里怎么建立；看懂 CLI 和守护进程怎么通信以及权限怎么判；知道 <code>tailscale up</code> 为什么要求重复参数</td><td>用熟之后，或者你要排查它内部行为的时候</td></tr><tr><td>本页</td><td>选功能、查官方入口</td><td>随时回查</td></tr></tbody></table><p>建议顺序：<strong>先教程，后源码。</strong> 教程里的「安全与隐私要点」不要跳过，尤其是不打算只自己一个人用的时候。</p><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://tailscale.com/docs/concepts/what-is-tailscale" target="_blank" rel="noreferrer">What is Tailscale?</a>：它是什么、解决谁的什么问题。</li><li><a href="https://tailscale.com/docs/reference/connection-types" target="_blank" rel="noreferrer">Connection types</a>：直连、DERP、Peer Relay 的建立顺序，以及怎么判断当前是哪一种。</li><li><a href="https://tailscale.com/docs/concepts/control-data-planes" target="_blank" rel="noreferrer">Control and data planes</a>：协调服务器负责什么、不负责什么。</li><li><a href="https://tailscale.com/docs/concepts/can-tailscale-decrypt-traffic" target="_blank" rel="noreferrer">Can Tailscale decrypt my traffic?</a>：关于流量隐私的一页短问答。</li><li><a href="https://tailscale.com/docs/features/tailscale-ssh" target="_blank" rel="noreferrer">Tailscale SSH</a>：工作方式、规则语法、限制。</li><li><a href="https://tailscale.com/docs/features/tailscale-serve" target="_blank" rel="noreferrer">Tailscale Serve</a> 与 <a href="https://tailscale.com/docs/features/tailscale-funnel" target="_blank" rel="noreferrer">Tailscale Funnel</a>：各自的工作方式和限制。</li><li><a href="https://tailscale.com/docs/features/subnet-routers" target="_blank" rel="noreferrer">Subnet routers</a> 与 <a href="https://tailscale.com/docs/features/exit-nodes" target="_blank" rel="noreferrer">Exit nodes</a>：各平台的配置步骤。</li><li><a href="https://tailscale.com/docs/features/tailnet-policy-file" target="_blank" rel="noreferrer">Tailnet policy file</a>：策略文件有哪些段，各管什么。</li><li><a href="https://tailscale.com/docs/reference/tailscale-cli" target="_blank" rel="noreferrer">Tailscale CLI</a>：全部子命令和参数。</li><li><a href="https://tailscale.com/pricing" target="_blank" rel="noreferrer">Tailscale pricing</a>：套餐、附加项和计费 FAQ。</li><li><a href="https://tailscale.com/docs/reference/best-practices/security" target="_blank" rel="noreferrer">Best practices to secure your tailnet</a>：官方的安全基线与进阶清单。</li><li><a href="https://tailscale.com/docs/llms.txt" target="_blank" rel="noreferrer">Tailscale Documentation</a>：官方文档全站的索引，本页家族表的来源。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./tailscale.html">教程</a>：本目录的上手教程。</li><li><a href="./source.html">源码解读</a>：本目录的源码级解读。</li><li><a href="./../uu-remote/">UU Remote</a>：远程桌面类工具。对比「网络层打洞让设备互通」与「画面串流」两种思路。</li><li><a href="./../t3code/">T3 Code</a>：它的仓库里有 <code>packages/tailscale</code>。</li><li><a href="./../cindy/">Cindy</a>、<a href="./../codex/dot.html">Codex dot</a>：同批的姊妹页，属于远程与智能体工作位主题。</li><li><a href="/zh/products/claude/">Claude</a>、<a href="/zh/products/codex/">Codex</a>：可以放在远程工位上运行的 agent。</li><li><a href="/zh/products/ollama.html">Ollama</a>：想从外面访问的本地模型服务的一个例子。</li></ul>',29)])])}const b=e(s,[["render",d]]);export{m as __pageData,b as default};
